head -3 /Users/kalyan.venkata/software-engineering/.claude/sessions/*.jsonl 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line or line.startswith('==>'):
        continue
    try:
        obj = json.loads(line)
        print(json.dumps(obj, indent=2)[:500])
        print('---')
    except:
        pass
" 2>/dev/null || echo "No session files or parse error"
